//! Material Design Icons name → glyph lookup (table generated by build.rs).

include!(concat!(env!("OUT_DIR"), "/mdi_codepoints.rs"));

/// Glyph for `mdi:name` (or bare `name`). Unknown names map to `help-circle-outline`.
pub fn glyph(icon: &str) -> char {
    let name = icon
        .strip_prefix("mdi:")
        .or_else(|| icon.strip_prefix("hass:"))
        .unwrap_or(icon);
    lookup(name)
        .or_else(|| lookup("help-circle-outline"))
        .and_then(char::from_u32)
        .unwrap_or('\u{FFFD}')
}

fn lookup(name: &str) -> Option<u32> {
    MDI_CODEPOINTS
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .map(|i| MDI_CODEPOINTS[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_icons() {
        assert_eq!(glyph("mdi:home"), '\u{F02DC}');
        assert_eq!(glyph("lightbulb"), '\u{F0335}');
        assert_eq!(
            glyph("mdi:does-not-exist"),
            glyph("mdi:help-circle-outline")
        );
        assert!(MDI_CODEPOINTS.len() > 7000);
    }
}
